import{_ as r,l as o,o as e,c as i,v as t,p as s,x as l,d as p,i as T,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"结算周期","description":"","frontmatter":{"title":"结算周期","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/settlement-cycle.md","filePath":"quant/settlement-cycle.md","lastUpdated":1789023840000}'),E={name:"quant/settlement-cycle.md"};function h(c,a,A,_,u,B){const n=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="结算周期" tabindex="-1">结算周期 <a class="header-anchor" href="#结算周期" aria-label="Permalink to &quot;结算周期&quot;">​</a></h1><div class="epigraph"><p>成交日你锁定了价格，交收日才换券与钱。回测若在成交日就把现金与持仓同时更新，会低估在途占用，也会把尚未交收的券拿去再卖。</p><footer>—— 据 DTCC / 交易所结算规则；SEC 将美股周期改为 T+1 的实施说明整理</footer></div><p>上一课<a href="/quant/ccp-clearing">中央对手清算</a>把清算保证金做成每日现金。证券现货还有交收周期：T+1、曾经的 T+2/T+3。本课补成交日与交收日的差。资金成本课会把在途与融资利率乘起来；本课先禁止「成交即持有、成交即现金」的记账。不重写 CCP 初始保证金。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日频回测通常在收盘信号、次日开盘或同日收盘成交，然后立刻更新持仓与现金。真实流程是：成交日（T）锁定交易，结算日（T+\\(n\\)）交付。卖出所得现金在结算日前不可无约束地再投资；买入的券在结算日前可能不可再交收卖出或不可用于出借。缺口是状态机拆成<strong>交易账</strong>与<strong>结算账</strong>。把 T+1 当成 T+0，换手策略会多出一天的资金周转，年化收益被放大。</p><p>各国与产品周期不同：股票、公司债、国债、基金申赎不是同一个 \\(n\\)。用今日 T+1 回填 2010 年美股 T+3 时代，是制度前视。</p><h3 id="结算失败不是价格回报" tabindex="-1">结算失败不是价格回报 <a class="header-anchor" href="#结算失败不是价格回报" aria-label="Permalink to &quot;结算失败不是价格回报&quot;">​</a></h3><p>失败（fail）产生罚息、买进补救或强制措施，损益不一定等于价格变动。回测把失败当成「没成交」或当成「照常持有」，都会错。本课把失败标成资金与交收事件，不把它写成 alpha。</p><p><span class="marginnote">除权日、股东记录日与结算周期互动：谁有权拿分红取决于记录日与交收是否完成。总回报课已要求加回分红；这里补的是你是否在记录日已经是登记股东。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每笔成交写入：成交日、结算日、应付/应收现金、应付/应收券。现金可用余额 = 账户现金 − 未结算应付 + 按规则可预支部分（若券商允许，要声明）。持仓分「已成交未结算」与「已结算」。卖空建立还要叠加借券资格，通常需要可交收的券。周期规则按当时市场：\\(n_t\\) 是时间序列，不是常数。</p><p>周转约束：当日卖出所得若不能用于当日买入，回测就不得用「先卖后买、现金净额为零」的日内轧差，除非声明同一托管下允许。很多纸面再平衡假设了这种轧差。</p>',12)),(e(),s(d,null,{default:l(()=>[T(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20T0%5B%22%E6%88%90%E4%BA%A4%E6%97%A5%E9%94%81%E5%AE%9A%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20SET%5B%22%E7%BB%93%E7%AE%97%E6%97%A5%E4%BA%A4%E6%94%B6%22%5D%0A%20%20SET%20--%3E%20CASH%5B%22%E7%8E%B0%E9%87%91%E5%8F%AF%E7%94%A8%22%5D%0A%20%20SET%20--%3E%20POS%5B%22%E5%8F%AF%E5%86%8D%E4%BA%A4%E6%94%B6%E6%8C%81%E4%BB%93%22%5D%0A%20%20T0%20-.-%3E%7C%22%E8%AF%AF%E8%AE%B0%E7%AB%8B%E5%8D%B3%E4%BA%A4%E6%94%B6%22%7C%20BIAS%5B%22%E5%A4%B8%E5%A4%A7%E5%91%A8%E8%BD%AC%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>T+2 世界里，周一买、周二卖，周二晚上你可能仍欠着周一的应付资金，同时周二的应收还没到。纸面净值把这两笔轧成零占用，实盘要垫一天。回测至少对换手策略加「未结算占用」状态变量。周期切换日（T+3→T+2→T+1）分段执行，把后来的快周转送给早期样本，是制度前视。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>周期拉长占用，缩短释放占用。T+3 到 T+1 的制度变迁提高了周转速度，历史回测必须用当时 \\(n\\)，否则把后来的效率送给过去的策略。事件日两侧的交易尤其敏感：公告日买入、次日卖出，在 T+2 世界可能两笔都未结算完，资金双占用。这与财报窗口的「隔夜 alpha」叠在一起时，纸面收益含不可用的现金。</p><p><span class="marginnote">CCP 的变动保证金按营业日；现货结算按 T+\\(n\\)。同一账户两条时钟，危机里两边同时要现金。</span></p><p>每笔成交拆成成交日与结算日两行账。可用现金不含未结算应收，除非声明券商预支规则。\\(n_t\\) 用当时市场：美股 T+3/T+2/T+1 分段，不要全样本 T+1。日频再平衡若依赖「先卖后买当日轧差」，必须声明同一托管允许，否则买入腿要等到卖出结算或动用额外现金。除权记录日与交收是否完成对齐，避免把未结算买入当成已登记股东去收分红。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写各国结算系统架构，不估计 CSD 失败率模型。下一课<a href="/quant/funding-cost-floor">资金成本作为 alpha 底</a>把占用 × 利率收成硬约束。后课默认：持仓与现金按结算日可用；周期用当时规则，不用今日 T+1 回填。</p><p>后课资金底把在途占用乘上利率。本课先禁止成交即持有。周期 \\(n_t\\) 分段 PIT。先卖后买的日内轧差不是默认权利。失败按交收事件处理，不把它的罚息写进价格 alpha。分红归属看记录日与交收是否完成，与财务课的除权三时点接上。</p><p>后课默认持仓与现金按结算日可用，周期 \\(n_t\\) 用当时规则；今日 T+1 不得回填 T+3 年代。</p><p>卖空建立通常需要可交收的券，未结算的多头不一定能拿去交收空头。状态机把「已成交未结算」与「已结算可交收」分开，避免同一张股票被同时当成多头库存与空头交收来源。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>成交锁定价格，结算才换券与钱。</li><li>立即更新现金与持仓会夸大换手策略的周转。</li><li>周期 \\(n\\) 是制度时间序列，必须 PIT。</li><li>未结算券不一定能再卖或出借。</li><li>失败是交收事件，不是价格 alpha。</li><li>出处：DTCC 与交易所结算规则；SEC T+1 实施说明。</li></ul>',12))])}const C=r(E,[["render",h]]);export{f as __pageData,C as default};
